def cumsum_sum(a, x, y, w, h) :
    w   = max(0, min(w, len(a[0]) - x))
    h   = max(0, min(h, len(a   ) - y))
    if  w and h :
        return(                a[y + h - 1][x + w - 1]
               - ((      y and a[y     - 1][x + w - 1]) or 0)
               - ((x and       a[y + h - 1][x     - 1]) or 0)
               + ((x and y and a[y     - 1][x     - 1]) or 0)
              )
    return(0)

